python3 -c "
import csv
dev=list(csv.DictReader(open('dev/customers_dev.csv')))
lab={r['customer_id']:r for r in csv.DictReader(open('dev/labels_dev.csv'))}
main=list(csv.DictReader(open('customers.csv')))
def key(r): return (r['full_name'],r['dob'],r['id_type'],r['id_number'],r['type'])
dk={}
for r in dev: dk.setdefault(key(r),[]).append(r['customer_id'])
hit=sum(1 for r in main if key(r) in dk)
print('main rows',len(main),'exact-tuple overlap with dev:',hit)
# name-only overlap
dn={}
for r in dev: dn.setdefault(r['full_name'],[]).append(r['customer_id'])
hit2=sum(1 for r in main if r['full_name'] in dn)
print('name-only overlap:',hit2)
"

python3 -c "
import csv,collections,json
dev={r['customer_id']:r for r in csv.DictReader(open('dev/customers_dev.csv'))}
lab=list(csv.DictReader(open('dev/labels_dev.csv')))
wl={e['uid']:e for e in json.load(open('watchlist.json'))}
byclass=collections.defaultdict(list)
for r in lab: byclass[r['class']].append(r)
for cls in sorted(byclass):
    print('==',cls,len(byclass[cls]))
    for r in byclass[cls][:3]:
        c=dev[r['customer_id']]
        e=wl.get(r['expected_uid'])
        print('   CUST:',c['full_name'],'|dob',c['dob'],'|',c['id_type'],c['id_number'],'|',c['type'])
        if e: print('   ENTRY:',e['primary_name'],'|',e['script_name'],'|dob',e['dob'],'|',[a['name']+':'+a['strength'] for a in e['aliases']],'|',e['ids'])
" 2>&1 | head -120
